from __future__ import annotations

import base64
from datetime import datetime
from pathlib import Path


PROJECT_ROOT = Path(__file__).resolve().parent
TARGET = PROJECT_ROOT / "app" / "ui" / "shipment_orders_page.py"

OPEN_SHIPMENT_DETAIL = base64.b64decode(
    ""
).decode("utf-8")

DETAIL_SELECTION = base64.b64decode(
    ""
).decode("utf-8")

DELETE_SELECTED_ITEM = base64.b64decode(
    ""
).decode("utf-8")


def replace_method(
    source: str,
    method_name: str,
    next_method_name: str,
    replacement: str,
) -> str:
    start_marker = f"    def {method_name}("
    end_marker = f"    def {next_method_name}("

    start = source.find(start_marker)
    if start < 0:
        raise RuntimeError(
            f"Method not found: {method_name}"
        )

    end = source.find(end_marker, start)
    if end < 0:
        raise RuntimeError(
            f"Next method not found: {next_method_name}"
        )

    return (
        source[:start]
        + replacement.rstrip()
        + "\n\n"
        + source[end:]
    )


def main() -> None:
    if not TARGET.exists():
        raise SystemExit(
            f"Target file not found: {TARGET}"
        )

    source = TARGET.read_text(
        encoding="utf-8-sig"
    )

    backup_dir = (
        PROJECT_ROOT
        / "backups"
        / "code_backups"
        / "local_snapshots"
    )
    backup_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    timestamp = datetime.now().strftime(
        "%Y%m%d_%H%M%S"
    )
    backup_path = backup_dir / (
        "shipment_orders_page_before_"
        f"delete_fix_{timestamp}.py"
    )
    backup_path.write_text(
        source,
        encoding="utf-8",
    )

    source = replace_method(
        source,
        "open_shipment_detail",
        "back_to_list",
        OPEN_SHIPMENT_DETAIL,
    )
    source = replace_method(
        source,
        "on_detail_selection_changed",
        "create_shipment",
        DETAIL_SELECTION,
    )
    source = replace_method(
        source,
        "delete_selected_item",
        "get_shipment",
        DELETE_SELECTED_ITEM,
    )

    TARGET.write_text(
        source,
        encoding="utf-8",
    )

    print("Shipment item delete fix applied.")
    print(f"Backup: {backup_path}")
    print(f"Updated: {TARGET}")


if __name__ == "__main__":
    main()
